// The released games, as generated by `npm run manifests`, and the filters find_games applies.
import generated from './data/catalog.generated.json' with { type: 'json' };
import type { Catalog,CatalogGame } from './data/types';
import { siteUrl,type Site } from './config';
import type { GameView } from './schemas';
import { BUILD_URI } from './shared';

/** The same lists as scripts/lib/manifest.ts (tests/text.test.ts keeps them in step). */
export const GENRES = ['Action','Adventure','Casual','Cozy','Farming','Learning','Puzzle','Racing','RPG','Simulation','Strategy'] as const;
export const DEVICES = ['Computer','Tablet','Phone'] as const;
export const MOODS = ['calm','cozy','cheerful','exciting','brainy','creative','curious'] as const;
export type Genre = typeof GENRES[number];
export type Device = typeof DEVICES[number];
export type Mood = typeof MOODS[number];

export const catalog = generated as Catalog;

export interface Filters { age?: number; genre?: Genre; device?: Device; minutes?: number; mood?: Mood }
/** Filters that may be dropped, in this order, when nothing matches. Age is never relaxed. */
const RELAXABLE = ['mood','minutes'] as const;

const fits = (game: CatalogGame,f: Filters) =>
  (f.age === undefined || game.minAge <= f.age) &&
  (!f.genre || game.genres.includes(f.genre)) &&
  (!f.device || game.devices.includes(f.device)) &&
  (f.minutes === undefined || (!!game.sessionMinutes && game.sessionMinutes[0] <= f.minutes)) &&
  (!f.mood || game.moods.includes(f.mood));

/** Games that fit every filter, in the website's order. When none do, mood and then time are relaxed (never age). */
export function findGames(games: CatalogGame[],filters: Filters): { games: CatalogGame[]; relaxed: (keyof Filters)[] } {
  const relaxed: (keyof Filters)[] = [], current = { ...filters };
  let found = games.filter(game => fits(game,current));
  for (const key of RELAXABLE) {
    if (found.length || current[key] === undefined) continue;
    delete current[key]; relaxed.push(key);
    found = games.filter(game => fits(game,current));
  }
  return { games: found,relaxed };
}

export const findGame = (games: CatalogGame[],slug: string) => games.find(game => game.slug === slug);
export const plays = (game: CatalogGame) => game.embed !== 'site' && !!game.build;

/** What tools and widgets say about one game: everything a card needs, with absolute URLs. */
export function summary(game: CatalogGame,site: Site): GameView {
  return {
    slug: game.slug,title: game.title,tagline: game.tagline,pitch: game.pitch,ages: game.ageRange,minAge: game.minAge,
    genres: game.genres,devices: game.devices,controls: game.controls,moods: game.moods,
    ...(game.sessionMinutes ? { sessionMinutes: game.sessionMinutes } : {}),
    playTime: game.playTime,contentNotes: game.contentNotes,quickStart: game.quickStart,
    embed: plays(game) ? game.embed : 'site',
    url: siteUrl(site,game.page),cover: siteUrl(site,game.cover),...(game.logo ? { logo: siteUrl(site,game.logo) } : {}),
    accentColor: game.accentColor,...(game.community ? { madeBy: game.community.handle } : {}),
    ...(plays(game) && game.build ? { build: { url: siteUrl(site,game.build.path),uri: BUILD_URI(game.slug),bytes: game.build.bytes,sha256: game.build.sha256 } } : {})
  };
}
